fun {ι} {oSpec} {Stmt₁ Stmt₂ Stmt₃} {m n} {pSpec₁} {pSpec₂}
    [(i : pSpec₁.MessageIdx) → OracleInterface (pSpec₁.Message i)]
    [(i : pSpec₂.MessageIdx) → OracleInterface (pSpec₂.Message i)] {ιₛ₁} {OStmt₁}
    [(i : ιₛ₁) → OracleInterface (OStmt₁ i)] {ιₛ₂} {OStmt₂} [(i : ιₛ₂) → OracleInterface (OStmt₂ i)] {ιₛ₃} {OStmt₃}
    [(i : ιₛ₃) → OracleInterface (OStmt₃ i)] V₁ V₂ =>
  {
    verify := fun stmt challenges => do
      let stmt₂ ← simulateQ firstQueryImpl (V₁.verify stmt challenges.fst)
      simulateQ (secondQueryImpl V₁ challenges.fst) (V₂.verify stmt₂ challenges.snd),
    outputOracle := Sum.inr (appendOutputSimulation V₁ V₂) }

fun {ι} {oSpec} {Statement ιₛ} {OStatement} [(i : ιₛ) → OracleInterface (OStatement i)] =>
  { verify := fun stmt x => pure stmt,
    outputOracle := Sum.inl { embed := Function.Embedding.inl, hEq := ⋯, outputInterface_heq := ⋯ } }

fun {ι} {oSpec} {OuterStmtIn OuterStmtOut Outer_ιₛᵢ} {OuterOStmtIn} [(i : Outer_ιₛᵢ) → OracleInterface (OuterOStmtIn i)]
    {Outer_ιₛₒ} {OuterOStmtOut} [(i : Outer_ιₛₒ) → OracleInterface (OuterOStmtOut i)] {Inner_ιₛᵢ} {InnerOStmtIn}
    [(i : Inner_ιₛᵢ) → OracleInterface (InnerOStmtIn i)] {Inner_ιₛₒ} {InnerOStmtOut}
    [(i : Inner_ιₛₒ) → OracleInterface (InnerOStmtOut i)] {InnerStmtIn InnerStmtOut} {n} {pSpec}
    [(i : pSpec.MessageIdx) → OracleInterface (pSpec.Message i)] lens V output =>
  {
    verify := fun outerStmt challenges =>
      OptionT.mk
        (Option.map (lens.liftStmt outerStmt) <$>
          simulateQ (OracleVerifier.liftContextQueryImpl lens outerStmt)
            (V.verify (lens.projStmt outerStmt) challenges).run),
    outputOracle := output.outputOracle }

fun {ι} {oSpec} {OuterStmtIn OuterStmtOut Outer_ιₛᵢ} {OuterOStmtIn} [(i : Outer_ιₛᵢ) → OracleInterface (OuterOStmtIn i)]
    {Outer_ιₛₒ} {OuterOStmtOut} [(i : Outer_ιₛₒ) → OracleInterface (OuterOStmtOut i)] {Inner_ιₛᵢ} {InnerOStmtIn}
    [(i : Inner_ιₛᵢ) → OracleInterface (InnerOStmtIn i)] {Inner_ιₛₒ} {InnerOStmtOut}
    [(i : Inner_ιₛₒ) → OracleInterface (InnerOStmtOut i)] {InnerStmtIn InnerStmtOut} {n} {pSpec}
    [(i : pSpec.MessageIdx) → OracleInterface (pSpec.Message i)] lens outerStmt =>
  (QueryImpl.id' oSpec).addLift ((lens.simulateInput outerStmt).addLift (QueryImpl.id' [pSpec.Message]ₒ))

fun {ι} {oSpec} {StmtIn WitIn StmtOut WitOut} {n} {pSpec}
    [(i : pSpec.ChallengeIdx) → SampleableType (pSpec.Challenge i)] {σ} init impl {ιₛᵢ} {OStmtIn} {ιₛₒ} {OStmtOut}
    [(i : ιₛᵢ) → OracleInterface (OStmtIn i)] [(i : ιₛₒ) → OracleInterface (OStmtOut i)]
    [(i : pSpec.MessageIdx) → OracleInterface (pSpec.Message i)] relIn relOut verifier rbrKnowledgeError =>
  Verifier.rbrKnowledgeSoundness init impl relIn relOut verifier.toVerifier rbrKnowledgeError

fun {ι} {oSpec} {m} Stmt {ιₛ} OStmt [Oₛ : (i : Fin (m + 1)) → (j : ιₛ i) → OracleInterface (OStmt i j)] {n} {pSpec}
    [Oₘ : (i : Fin m) → (j : (pSpec i).MessageIdx) → OracleInterface ((pSpec i).Message j)] V =>
  OracleVerifier.seqCompose' Stmt OStmt Oₛ Oₘ V

fun {ι} {oSpec} {Stmt₁ Stmt₂ Stmt₃} {m n} {pSpec₁} {pSpec₂}
    [(i : pSpec₁.MessageIdx) → OracleInterface (pSpec₁.Message i)]
    [(i : pSpec₂.MessageIdx) → OracleInterface (pSpec₂.Message i)] {ιₛ₁} {OStmt₁}
    [(i : ιₛ₁) → OracleInterface (OStmt₁ i)] {ιₛ₂} {OStmt₂} [(i : ιₛ₂) → OracleInterface (OStmt₂ i)] {ιₛ₃} {OStmt₃}
    [(i : ιₛ₃) → OracleInterface (OStmt₃ i)] V₁ V₂ =>
  {
    materializeOutput := fun challenges oStmt messages =>
      V₂.materializeOutput challenges.snd (V₁.materializeOutput challenges.fst oStmt messages.fst) messages.snd,
    simulateOutputQuery := fun challenges q =>
      simulateQ (secondQueryImpl V₁ challenges.fst) (V₂.simulateOutputQuery challenges.snd q),
    simulateOutputQuery_eq := ⋯ }

